 trials.append({'query':qid,'question':q,'expected':want,'chronological_output':gotA,'decision_index_output':gotB,'same_scoped_findings':set(gotA)==set(gotB),'chronological_entries_considered':4,'indexed_entries_considered':len(gotB)})
